class Solution:
    def countWays(self, ranges: List[List[int]]) -> int:
        ranges.sort()
        groups = 1
        end = ranges[0][1]
        for s, e in ranges[1:]:
            if s <= end:
                end = max(end, e)
            else:
                groups += 1
                end = e
        return pow(2, groups, 10**9 + 7)

c.cpp:
class Solution {
public:
    int countWays(vector<vector<int>>& ranges) {
        sort(ranges.begin(), ranges.end());
        long long groups = 1, end = ranges[0][1];
        for (auto& r : ranges) {
            if (r[0] <= end) end = max(end, (long long)r[1]);
            else { groups++; end = r[1]; }
        }
        long long ans = 1, MOD = 1e9 + 7;
        for (long long i = 0; i < groups; i++) ans = ans * 2 % MOD;
        return (int)ans;
    }
};

