class Solution {
    public int countWays(int[][] ranges) {
        Arrays.sort(ranges, (a, b) -> Integer.compare(a[0], b[0]));
        long groups = 1, end = ranges[0][1];
        for (int[] r : ranges) {
            if (r[0] <= end) end = Math.max(end, r[1]);
            else { groups++; end = r[1]; }
        }
        long ans = 1, MOD = (long) 1e9 + 7;
        for (long i = 0; i < groups; i++) ans = ans * 2 % MOD;
        return (int) ans;
    }
}

