var countWays = function(ranges) {
    ranges.sort((a, b) => a[0] - b[0]);
    let groups = 1, end = ranges[0][1];
    for (const [s, e] of ranges) {
        if (s <= end) end = Math.max(end, e);
        else { groups++; end = e; }
    }
    let ans = 1;
    for (let i = 0; i < groups; i++) ans = ans * 2 % 1000000007;
    return ans;
};
